CREATE TABLE buyer_interests(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`listing_id` bigint  NOT NULL,`buyer_name` varchar(255)  NOT NULL,`buyer_phone` varchar(255)  NOT NULL,`buyer_email` varchar(255)  NULL,`buyer_type` varchar(255)  NOT NULL COMMENT 'wholesaler, retailer, processor, cooperative',`interested_quantity` INT  NOT NULL COMMENT 'Quantity in kg',`message` text  NULL,`status` varchar(255)  DEFAULT 'pending' COMMENT 'pending, contacted, agreed, cancelled',`delivery_latitude` DECIMAL(10,8)  NULL COMMENT 'Buyer delivery location GPS latitude (optional)',`delivery_longitude` DECIMAL(11,8)  NULL COMMENT 'Buyer delivery location GPS longitude (optional)',`delivery_pincode` varchar(10)  NULL COMMENT 'Buyer delivery location postal code',`delivery_state` varchar(100)  NULL COMMENT 'Buyer delivery location state',`delivery_district` varchar(100)  NULL COMMENT 'Buyer delivery location district',`delivery_village` varchar(100)  NULL COMMENT 'Buyer delivery location village/VPO',`delivery_address_line` varchar(255)  NULL COMMENT 'Full buyer delivery address')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;